run.command:
set -euo pipefail
tool_dir="${QQQ_TEMPLATE_TOOL_DIR:-$HOME/.cache/qqq-template-renderer}"
output="${QQQ_TEMPLATE_OUTPUT:-$HOME/qqq-template-acceptance}"
work="${QQQ_TEMPLATE_WORK:-/tmp/qqq-template-check}"
mkdir -p "$work"
curl --fail --silent --show-error --location --retry 2 --max-time 60 https://raw.githubusercontent.com/QRun-IO/qqq-templates-hub/4d22fc650967eee609107476d5dc3ac5dffeb071/templates.yaml -o "$work/catalog.yaml"
echo "9342ef716f11ffea25a684fba6865e4daf303d968b5fa6a1ddcc6de43a6bb193  $work/catalog.yaml" | sha256sum --check --status
cat > "$work/QqqTemplateCheck.java" \<<'JAVA'
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import io.qrun.qctl.qqq.template.TemplateEngine;
import io.qrun.qctl.qqq.template.TemplateManifest;
import io.qrun.qctl.qqq.template.TransformExecutor;

public class QqqTemplateCheck
{
   public static void main(String[] args) throws Exception
   {
      if(args.length != 3)
      {
         throw new IllegalArgumentException("Expected catalog, checked-out template, fresh output directory");
      }
      Path output = Path.of(args[2]);
      if(Files.exists(output))
      {
         throw new IllegalArgumentException("Output directory must not exist");
      }
      ObjectMapper mapper = new ObjectMapper(new YAMLFactory());
      JsonNode index = mapper.readTree(Path.of(args[0]).toFile());
      TemplateManifest manifest = null;
      for(JsonNode entry : index.get("templates"))
      {
         if("new-qqq-application".equals(entry.path("id").asText()))
         {
            if(manifest != null) throw new IllegalArgumentException("Duplicate template entry");
            manifest = mapper.treeToValue(entry, TemplateManifest.class);
         }
      }
      if(manifest == null) throw new IllegalArgumentException("Template missing from catalog");
      TemplateEngine engine = new TemplateEngine();
      Map<String, String> variables = new LinkedHashMap<>(Map.of(
         "projectName", "ci-template", "groupId", "io.qrun.ci",
         "artifactId", "ci-template", "packageName", "io.qrun.ci"));
      variables = engine.evaluateComputed(manifest.computed(), variables);
      Files.createDirectories(output);
      int count = engine.render(Path.of(args[1]), output, variables, manifest);
      if(manifest.transforms() != null)
      {
         new TransformExecutor().execute(output, manifest.transforms(), variables);
      }
      if(count == 0 || !Files.isRegularFile(output.resolve("pom.xml")))
      {
         throw new IllegalStateException("Renderer did not create the application");
      }
      System.out.println("Rendered " + count + " files from the exact local template; hooks not executed");
   }
}
JAVA
java -cp "$(cat "$tool_dir/classpath.txt"):$tool_dir/qctl-qqq/target/classes" "$work/QqqTemplateCheck.java" "$work/catalog.yaml" "$PWD" "$output"
